      "name": "one_le_pow₀",
      "module_name": "Mathlib.Algebra.Order.GroupWithZero.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {M₀ : Type u_2} [inst : MonoidWithZero M₀] [inst_1 : Preorder M₀] {a : M₀} [ZeroLEOneClass M₀] [PosMulMono M₀],\n  1 ≤ a → ∀ {n : ℕ}, 1 ≤ a ^ n"
    },
    {
      "name": "NeZero.pow",
      "module_name": "Mathlib.Algebra.GroupWithZero.Basic",
      "kind": "instance",
      "type": "∀ {M₀ : Type u_1} [inst : MonoidWithZero M₀] {a : M₀} {n : ℕ} [IsReduced M₀] [NeZero a], NeZero (a ^ n)"
    },
    {
      "name": "one_le_mul_of_one_le_of_one_le",
      "module_name": "Mathlib.Algebra.Order.GroupWithZero.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {M₀ : Type u_2} [inst : MonoidWithZero M₀] [inst_1 : Preorder M₀] {a b : M₀} [ZeroLEOneClass M₀] [PosMulMono M₀],\n  1 ≤ a → 1 ≤ b → 1 ≤ a * b"
    },
    {
      "name": "pow_succ_pos",
      "module_name": "Mathlib.Algebra.Order.GroupWithZero.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {M₀ : Type u_2} [inst : MonoidWithZero M₀] [inst_1 : PartialOrder M₀] {a : M₀} [PosMulStrictMono M₀],\n  0 < a → ∀ (n : ℕ), 0 < a ^ (n + 1)"
    },
    {
      "name": "Bound.le_self_pow_of_pos",
      "module_name": "Mathlib.Algebra.Order.GroupWithZero.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {M₀ : Type u_2} [inst : MonoidWithZero M₀] [inst_1 : Preorder M₀] {a : M₀} {n : ℕ} [ZeroLEOneClass M₀]\n  [PosMulMono M₀], 1 ≤ a → 0 < n → a ≤ a ^ n"
    }
  ]
}
